<div id="kategori-modal" class="fixed inset-0 z-[100] hidden items-center justify-center bg-black/40 p-4"><div class="absolute inset-0" onclick="closeKategoriModal()"></div><div class="relative w-full max-w-xl rounded-xl bg-white shadow-2xl"><div class="flex justify-between border-b border-outline-variant px-6 py-4"><h2 id="kategori-title" class="text-xl font-semibold">Tambah Kategori Baru</h2><button type="button" onclick="closeKategoriModal()"><span class="material-symbols-outlined">close</span></button></div><form id="kategori-form" method="POST" action="<?php echo e(route('master-kategori.store')); ?>" class="space-y-4 p-6"><?php echo csrf_field(); ?><div><label class="mb-1 block font-semibold">Kode Kategori</label><input value="[otomatis]" readonly class="w-full rounded-md border border-outline-variant bg-surface-container-low px-3 py-2 text-on-surface-variant"></div><div><label class="mb-1 block font-semibold">Nama Kategori *</label><input id="kategori-nama" name="nm_master_kategori" required class="w-full rounded-md border border-outline-variant px-3 py-2"></div><div><label class="mb-1 block font-semibold">Deskripsi</label><textarea id="kategori-desc" name="desc_master_kategori" rows="3" class="w-full rounded-md border border-outline-variant px-3 py-2"></textarea></div><div><label class="mb-1 block font-semibold">Status *</label><select id="kategori-status" name="status_master_kategori" required class="w-full rounded-md border border-outline-variant px-3 py-2"><option>AKTIF</option><option>TIDAK AKTIF</option></select></div><div class="flex justify-end gap-2 border-t border-outline-variant pt-4"><button type="button" onclick="closeKategoriModal()" class="rounded-md border px-4 py-2">Batal</button><button class="rounded-md bg-primary px-5 py-2 font-label-bold text-on-primary">Simpan</button></div></form></div></div><script>function openKategoriModal(){const m=document.getElementById('kategori-modal');m.classList.remove('hidden');m.classList.add('flex');documen